entries.command:
WITH active_users AS (
  SELECT * FROM users WHERE last_login > NOW() - INTERVAL '30 days'
)
SELECT department, COUNT(*) FROM active_users GROUP BY department;

SELECT date, amount,
  SUM(amount) OVER (ORDER BY date) AS running_total
FROM transactions;

SELECT u.name, latest.title FROM users u
CROSS JOIN LATERAL (
  SELECT title FROM posts p
  WHERE p.user_id = u.id
  ORDER BY created_at DESC LIMIT 3
) latest;

SELECT date::date, COALESCE(count, 0)
FROM generate_series('2024-01-01', '2024-12-31', '1 day') AS date
LEFT JOIN daily_counts ON daily_counts.day = date::date;

DELETE FROM items
WHERE archived_at < NOW() - INTERVAL '1 year'
RETURNING id, title;
